BEGIN TRANSACTION;
CREATE TABLE analytics_snapshots (
  computed_at TEXT,
  date_from TEXT,
  date_to TEXT,
  id INTEGER PRIMARY KEY,
  payload TEXT,
  snapshot_type TEXT
);
CREATE TABLE app_settings (
  id INTEGER PRIMARY KEY,
  payload TEXT,
  setting_type TEXT,
  updated_at TEXT,
  updated_by TEXT
);
CREATE TABLE invoice_settings (
  developed_by TEXT,
  developed_by_url TEXT,
  hospital_name TEXT,
  id INTEGER PRIMARY KEY,
  is_active INTEGER,
  logo_path TEXT,
  online_report_url TEXT,
  printer_width TEXT,
  qr_code_path TEXT,
  updated_at TEXT
);
CREATE TABLE patients (
  age INTEGER,
  cnic TEXT,
  created_at TEXT,
  gender TEXT,
  id INTEGER,
  mobile TEXT,
  mr_no INTEGER PRIMARY KEY,
  patient_name TEXT,
  patient_token INTEGER,
  pwd TEXT,
  relation TEXT,
  relation_name TEXT,
  salutation TEXT,
  shift TEXT,
  user TEXT,
  user_id INTEGER
);
CREATE TABLE print_settings (
  bg_light TEXT,
  border_color TEXT,
  category_border_width INTEGER,
  category_font_size INTEGER,
  category_padding_bottom INTEGER,
  category_padding_top INTEGER,
  col_range_align TEXT,
  col_range_width INTEGER,
  col_result_align TEXT,
  col_result_width INTEGER,
  col_test_name_align TEXT,
  col_test_name_width INTEGER,
  col_unit_align TEXT,
  col_unit_width INTEGER,
  combine_categories_on_same_page INTEGER,
  created_at TEXT,
  created_by TEXT,
  display_pathologist_signature INTEGER,
  display_verified_by INTEGER,
  footer_font_size INTEGER,
  footer_line1 TEXT,
  footer_line2 TEXT,
  footer_line3 TEXT,
  footer_margin_top INTEGER,
  footer_padding_top INTEGER,
  group_font_size INTEGER,
  group_padding_bottom INTEGER,
  group_padding_left INTEGER,
  group_padding_top INTEGER,
  header_bottom_margin INTEGER,
  header_height INTEGER,
  hide_single_param_title INTEGER,
  id INTEGER PRIMARY KEY,
  is_active INTEGER,
  page_bottom_margin INTEGER,
  page_left_margin INTEGER,
  page_right_margin INTEGER,
  page_top_margin INTEGER,
  patient_info_border_radius INTEGER,
  patient_info_bottom_margin INTEGER,
  patient_info_font_size INTEGER,
  patient_info_label_font_size INTEGER,
  patient_info_label_width INTEGER,
  patient_info_min_height INTEGER,
  patient_info_padding_horizontal INTEGER,
  patient_info_padding_vertical INTEGER,
  patient_info_row_gap INTEGER,
  primary_color TEXT,
  result_font_size INTEGER,
  secondary_color TEXT,
  signature_block_min_width INTEGER,
  table_cell_padding_horizontal INTEGER,
  table_cell_padding_vertical INTEGER,
  table_header_padding_horizontal INTEGER,
  table_header_padding_vertical INTEGER,
  test_name_font_size INTEGER,
  text_main TEXT,
  text_muted TEXT,
  updated_at TEXT,
  updated_by TEXT
);
CREATE TABLE remarks (
  category TEXT,
  created_at TEXT,
  id INTEGER PRIMARY KEY,
  is_active INTEGER,
  remark_text TEXT,
  sort_order INTEGER,
  test_name TEXT,
  updated_at TEXT,
  usage_count INTEGER
);
CREATE TABLE shift (
  created_at TEXT,
  id INTEGER PRIMARY KEY,
  shift TEXT
);
CREATE TABLE test_groups (
  category TEXT,
  component_ids TEXT,
  created_at TEXT,
  group_name TEXT,
  id INTEGER PRIMARY KEY,
  status INTEGER
);
CREATE TABLE test_results_all (
  category TEXT,
  created_at TEXT,
  delete_status INTEGER,
  id INTEGER PRIMARY KEY,
  mr_no INTEGER,
  patient_name TEXT,
  person_deleting TEXT,
  remarks TEXT,
  status TEXT,
  test_name TEXT,
  test_values TEXT
);
CREATE TABLE tests (
  category TEXT,
  created_at TEXT,
  id INTEGER PRIMARY KEY,
  name TEXT,
  normal_max TEXT,
  normal_min TEXT,
  status INTEGER,
  unit TEXT
);
CREATE TABLE users (
  created_at TEXT,
  default_shift_id INTEGER,
  email TEXT,
  id INTEGER PRIMARY KEY,
  is_active INTEGER,
  name TEXT,
  permissions TEXT,
  pwd TEXT
);
COMMIT;
